def isValidIPv6(s):
    hexdigits = "0123456789abcdefABCDEF"

    def good(g):
        if not 1 <= len(g) <= 4:
            return False
        for c in g:
            if c not in hexdigits:
                return False
        return True

    if ':::' in s:
        return False
    if '::' in s:
        if s.count('::') > 1:
            return False
        left, right = s.split('::')
        groups = (left.split(':') if left else []) + (right.split(':') if right else [])
        if len(groups) > 7:
            return False
    else:
        groups = s.split(':')
        if len(groups) != 8:
            return False
    return all(good(g) for g in groups)
